3	import java.util.List;
4	import java.util.function.Supplier;
5	
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.stereotype.Service;
8	
9	import com.example.starter.maintenance.api.ApiException;
10	import com.example.starter.maintenance.api.dto.AddReadingRequest;
11	import com.example.starter.maintenance.api.dto.CompleteMaintenanceRequest;
12	import com.example.starter.maintenance.api.dto.EquipmentResponse;
13	import com.example.starter.maintenance.api.dto.MaintenanceResponse;
14	import com.example.starter.maintenance.api.dto.ReadingResponse;
15	import com.example.starter.maintenance.api.dto.RegisterEquipmentRequest;
16	import com.example.starter.maintenance.api.dto.ReviseReadingRequest;
17	import com.example.starter.maintenance.api.dto.RevisionView;
18	import com.example.starter.maintenance.api.dto.StatusResponse;
19	
20	/**
21	 * 设备工时保养外观服务：委托事务服务执行；并发下唯一键冲突（事务已回滚）时，
22	 * 优先按 requestId 重放已提交的成功结果，否则转换为 409 业务冲突。
23	 */
24	@Service
25	public class EquipmentService {
26	
27	    private final EquipmentTxService txService;
28	    private final IdempotencyService idempotency;
29	
30	    public EquipmentService(EquipmentTxService txService, IdempotencyService idempotency) {
31	        this.txService = txService;
32	        this.idempotency = idempotency;
33	    }
34	
35	    public EquipmentResponse register(RegisterEquipmentRequest req) {
36	        String fingerprint = req.equipmentId() + "|" + req.maintenancePeriodMinutes();
37	        return recoverDuplicateKey(req.requestId(), "REGISTER_EQUIPMENT", fingerprint,
38	                EquipmentResponse.class, () -> txService.register(req));
39	    }
40	
41	    public ReadingResponse addReading(String equipmentId, AddReadingRequest req) {
42	        return txService.addReading(equipmentId, req);
43	    }
44	
45	    public ReadingResponse reviseReading(String equipmentId, String readingId, ReviseReadingRequest req) {
46	        return txService.reviseReading(equipmentId, readingId, req);
47	    }
48	
49	    public MaintenanceResponse completeMaintenance(String equipmentId, CompleteMaintenanceRequest req) {
50	        return txService.completeMaintenance(equipmentId, req);
51	    }
52	
53	    public StatusResponse getStatus(String equipmentId) {
54	        return txService.getStatus(equipmentId);
55	    }
56	
57	    public List<ReadingResponse> listReadings(String equipmentId) {
58	        return txService.listReadings(equipmentId);
59	    }
60	
61	    public List<RevisionView> listRevisions(String equipmentId, String readingId) {
62	        return txService.listRevisions(equipmentId, readingId);
63	    }
64	
65	    public List<MaintenanceResponse> listMaintenances(String equipmentId) {
66	        return txService.listMaintenances(equipmentId);
67	    }
68	
69	    /**
70	     * 并发唯一键冲突补偿：冲突事务已回滚，若同 requestId 的成功记录已提交则重放（异参抛 409），
71	     * 否则说明是业务唯一键冲突，返回 409。
72	     */
73	    private <T> T recoverDuplicateKey(String requestId, String operation, String fingerprint,
74	                                      Class<T> type, Supplier<T> action) {
75	        try {
76	            return action.get();
77	        } catch (DuplicateKeyException e) {
78	            T replayed = idempotency.replayExisting(requestId, operation, fingerprint, type);
79	            if (replayed != null) {
80	                return replayed;
81	            }
82	            throw ApiException.conflict("DUPLICATE_KEY", "唯一约束冲突，请核对业务标识是否已被占用");
83	        }
84	    }
85	}
