package com.example.starter.maintenance.api.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

/**
 * 创建（单设备）能源隔离令请求。隔离令创建后为 PENDING，须由 ISOLATOR、VERIFIER 两个不同
 * 维护角色分别确认全部锁定点后生效；锁定点集合创建时固化。
 *
 * @param requestId        全局唯一请求标识（幂等键）
 * @param expectedVersion  设备期望版本号，与当前版本不一致返回 409
 * @param operatorId       创建操作人
 * @param lockPoints       完整锁定点集合，至少 1 个；同令内标识重复返回 422
 */
public record CreateIsolationRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String operatorId,
        @NotEmpty @Valid List<@Valid LockPointSpec> lockPoints) {
}

package com.example.starter.maintenance.api.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

/**
 * 批量隔离中的单设备项：携带该设备的期望版本与完整锁定点集合。
 *
 * @param equipmentId      设备标识
 * @param expectedVersion  该设备期望版本号
 * @param lockPoints       该设备完整锁定点集合，至少 1 个
 */
public record BatchIsolationItemRequest(
        @NotBlank String equipmentId,
        @NotNull Long expectedVersion,
        @NotEmpty @Valid List<@Valid LockPointSpec> lockPoints) {
}

package com.example.starter.maintenance.api.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

/**
 * 批量隔离请求：一个 requestId 覆盖整批，先校验全部设备的完整后态，
 * 任一设备校验失败整批不生效；成功时所有隔离令在同一事务内提交。
 *
 * @param requestId  全局唯一请求标识（幂等键，整批共用）
 * @param operatorId 创建操作人（整批共用）
 * @param items      各设备隔离项；设备重复、锁定点重复等均导致整批 422
 */
public record BatchIsolationRequest(
        @NotBlank String requestId,
        @NotBlank String operatorId,
        @NotEmpty @Size(max = 100) @Valid List<@Valid BatchIsolationItemRequest> items) {
}

package com.example.starter.maintenance.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * 锁定点确认请求：一名操作人以一个维护角色确认一个锁定点。同一角色对同一锁定点
 * 重复确认返回 422；每个锁定点须经 ISOLATOR、VERIFIER 两个不同角色分别确认。
 *
 * @param requestId        全局唯一请求标识（幂等键）
 * @param expectedVersion  设备期望版本号（确认不推进版本，仅作乐观并发校验）
 * @param operatorId       确认操作人
 * @param lockRole         维护角色：ISOLATOR 上锁人 / VERIFIER 验证人
 * @param lockPointId      被确认的锁定点标识，须属于该设备当前活动隔离令
 */
public record ConfirmLockPointRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String operatorId,
        @NotBlank @Pattern(regexp = "ISOLATOR|VERIFIER") String lockRole,
        @NotBlank String lockPointId) {
}

package com.example.starter.maintenance.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 单个锁定点解除请求：隔离令生效后锁定点须逐一解除，每次解除必须填写原因。
 * 尚有锁定点未解除时结束隔离（整令解除）返回 422。
 *
 * @param requestId        全局唯一请求标识（幂等键）
 * @param expectedVersion  设备期望版本号（逐点解除不推进版本，仅作乐观并发校验）
 * @param operatorId       解除操作人
 * @param lockPointId      待解除锁定点标识；不属于活动令返回 422，已解除返回 422
 * @param reason           解除原因（必填）
 */
public record ReleaseLockPointRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String operatorId,
        @NotBlank String lockPointId,
        @NotBlank @Size(max = 512) String reason) {
}

