    @ResponseStatus(HttpStatus.CREATED)
    public BatchIsolationResponse createBatch(@Valid @RequestBody BatchIsolationRequest req) {
        return service.createBatchIsolation(req);
    }

    /** 对单台设备创建能源隔离令（锁定点集合随令固化）。 */
