        // 工时与保养历史字段未被隔离流程改写：读数表无被拒读数
        mockMvc.perform(get("/api/equipment/eq-hist/readings"))
                .andExpect(jsonPath("$.length()").value(0));
    }

    // ---------- 辅助 ----------

    private void createSimpleOrder(String equipmentId, String requestId, long expectedVersion)
