private List<Map<String, Object>> normalizeBatchItems(List<BatchIsolationItemRequest> items) {
    return items.stream()
            .sorted(java.util.Comparator.comparing(BatchIsolationItemRequest::equipmentId))
            .map(item -> {
                Map<String, Object> entry = new TreeMap<>();
